#include <bits/stdc++.h>
using namespace std;
class Solution {public:long long distinctNames(vector<string>& ideas){vector<unordered_set<string>> g(26);for(auto& s:ideas)g[s[0]-'a'].insert(s.substr(1));long long ans=0;for(int i=0;i<26;++i)for(int j=i+1;j<26;++j){int common=0;for(auto& x:g[i])if(g[j].count(x))++common;ans+=2LL*(g[i].size()-common)*(g[j].size()-common);}return ans;}};
